#!/usr/bin/env bash
# Generated by prepare-submission.sh. Run:
#   ADDR=0x<wallet> SIG=0x<65-byte EIP-191 signature of message.txt> bash upload.sh
set -euo pipefail
: "${ADDR:?set ADDR to the submitting wallet address}"
: "${SIG:?set SIG to the 65-byte hex EIP-191 signature of message.txt}"
HERE="$(cd "$(dirname "$0")" && pwd)"
NONCE="$(cat "$HERE/nonce.txt")"
curl -s -X POST "https://devnode.telegraphprotocol.com/api/evalpool/submissions?intent_id=DNS_RECORD_LOOKUP_GENERAL&submitter=$ADDR" \
  -H "Content-Type: application/x-ndjson" \
  -H "X-Evalpool-Signature: $SIG" \
  -H "X-Evalpool-Nonce: $NONCE" \
  --data-binary @"$HERE/items.jsonl"
